extraCss:
:root{--hero-focus:50% 0%;}
.hero--bleed[data-hero-mode="full"] .hero-img{object-position:var(--hero-focus);}
@media(max-width:800px){.hero--bleed[data-hero-mode="full"] .hero-img{object-position:50% 0%;}}
.guide-hero.pg-conversations>.wrap{grid-template-columns:minmax(0,1fr);}.pg-conversations .guide-hero-text{max-width:64ch;}
.pg-reach{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:2rem;align-items:center;margin:2rem 0;padding:1.5rem;border:1px solid var(--line);border-radius:0 24px 0 0;}.pg-reach figure{margin:0;max-width:472px;justify-self:center;}.pg-reach img{display:block;width:100%;height:auto;background:#000;}.pg-reach figcaption{font-size:.75rem;line-height:1.5;color:var(--ink-2);padding-top:.6rem;}.pg-reach h4{margin:.4rem 0 .8rem;}.pg-reach p{margin:0 0 .8rem;}@media(max-width:700px){.pg-reach{grid-template-columns:1fr;gap:1.25rem;padding:1rem;}}
#plans{padding-bottom:44px;}
#athletes-say{padding-top:32px;}.block#athletes-say{padding-bottom:32px;}.block#athletes-say + #events{padding-top:32px;background:color-mix(in srgb,var(--paper) 94%,white);}
.home-lab #story .story figure img{object-position:50% 100%;}
.guidance--raceday .art-photo img.shift-up[src*='/images/finish.jpg']{object-position:50% 20%;}
.art-photo img{object-position:50% 32%;}
#burpee-broad-jumps+figure.art-photo img{object-position:50% 45%;}
.tips-photo img{object-position:50% 28%;}
@media(max-width:900px){.tips-photo img[src*='/images/wallball.jpg'],.guidance .guide-hero-photo img[src*='/images/run-hero.jpg'],.community .guide-hero-photo img[src*='/images/events-secondary.jpg']{object-position:50% 0%;}.video-card img[src*='/images/coaching-hero.jpg']{object-position:50% 65%;}}
@media(max-width:600px){.hero--bleed .wrap{align-items:end;padding-bottom:26px;}#plans{padding-bottom:36px;}#athletes-say{padding-top:28px;}}
.guidance--field .guide-hero .guide-hero-photo img[src*='/images/stations-hero.jpg']{height:auto;max-height:none;aspect-ratio:1024/895;object-fit:contain;}
.guidance--coach .guide-hero .guide-hero-photo img{height:auto;max-height:none;aspect-ratio:849/1024;object-fit:contain;object-position:center;}
.pg-team{margin-bottom:2.5rem;}.pg-team-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.5rem;margin:1.5rem 0;}.pg-team-grid article{border-top:1px solid var(--line);padding-top:1rem;}.pg-team-grid h4{margin:0 0 .5rem;}.pg-offers .plan{min-width:0;}.pg-offers .btn{white-space:normal;text-align:center;}.pg-offer-detail{display:block;margin-top:1rem;font-size:.85rem;}.pg-price-note,.pg-source{font-size:.85rem;line-height:1.6;color:var(--ink-2);margin:1.2rem 0 2rem;}.pg-client-stories{margin-top:2.5rem;}.pg-client-stories .quote{background:var(--paper-2);color:var(--ink);}.pg-client-stories .quote footer{color:var(--ink-2);}.pg-client-stories .quote footer strong{color:var(--ink);}.pg-choice-intro{margin-bottom:1.5rem;}#athletes-say .quote footer{padding:12px 0 0;margin:0;line-height:1.6;}
@media(max-width:800px){.pg-team-grid{grid-template-columns:1fr;}}
/* Ask Paul: mobile bg focus shifts right so the portrait circle never covers the face */
@media(max-width:600px){.capture-bg{object-position:30% 75%;}}
/* Race-instrument pages never loaded guidance.css — port the hero partial-frame + curved bottom so results/splits/predictor heroes match the guidance treatment */
.race-instrument .guide-hero-photo{position:relative;}
.race-instrument .guide-hero-photo img{object-fit:cover;object-position:50% 30%;aspect-ratio:16/9;max-height:420px;border-radius:0 0 48% 8% / 0 0 7% 2%;}
.race-instrument .guide-hero-photo::after{content:"";position:absolute;width:56px;height:56px;left:-8px;top:-8px;border-left:2px solid var(--pink);border-top:2px solid var(--pink);pointer-events:none;}
@media(max-width:900px){.race-instrument .guide-hero-photo img{aspect-ratio:16/10;max-height:none;}}
@media(max-width:600px){body.race-instrument .guide-hero .guide-hero-photo{display:block;}}
